    public SysOperationStartResult startOperation()
    {
        this.metCheckExecutionModeForCustPayment();

        return next startOperation();
    }

    /// <summary>
    /// Relates to MPJ-15465. Check if execution mode requires changing.
    /// </summary>
    private void metCheckExecutionModeForCustPayment()
    {
        if(isRunningOnBatch() && METCustPaymJournalAutomation::checkSessionFlagInCache())               
        {
            // Running in batch and within context of DD automation process.
            // NB this is a workaround to get context from process. Required hooks
            // in the ER generation classes/services/controllers are not available
            // as the classes are currently marked 'internal'.
            // When running the DD process in batch, the ER process must be run
            // synchronously to ensure the posting and deposit slip generation wait
            // for the file generation to complete, and to capture the log details
            // against the original task.

            this.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        }
    }
